    char name[64];
    int kindId;
    AmodBonusKindHandler buildFns[BonusesMaxKindHooks];
    int buildCnt;
    AmodBonusKindHandler updateFns[BonusesMaxKindHooks];
    int updateCnt;
    AmodBonusKindHandler takeFns[BonusesMaxKindHooks];
    int takeCnt;
} BonusesKindSlot;

static BonusesKindSlot g_bonuses_kinds[BonusesMaxKinds];
static int g_bonuses_kind_cnt = 0;

static AmodBonusType g_bonuses_sel_type;
static char g_bonuses_sel_type_name[BonusesTextCap];
static char g_bonuses_sel_type_res[BonusesTextCap];

static AmodBonusSpawnInfo g_bonuses_sel_pl;
