static char g_bonuses_body_tex_buf[BonusesTextCap];
static float g_bonuses_kind_dt = 0.0f;
static int g_bonuses_last_chain_pts = 0;

static MOD_UNUSED void bonuses_copy_str(char* dst, int cap, const char* src) {
    int i = 0;
    if (dst == 0 || cap <= 0) return;
    if (src != 0) {
        while (src[i] != 0 && i < cap - 1) { dst[i] = src[i]; ++i; }
    }
    dst[i] = 0;
}

static MOD_UNUSED int bonuses_str_eq(const char* a, const char* b) {
    if (a == 0 || b == 0) return 0;
    return strcmp(a, b) == 0 ? 1 : 0;
}

static MOD_UNUSED int bonuses_floor_cell(float v) {
    int whole = (int)v;
    return (v < 0.0f && (float)whole != v) ? (whole - 1) : whole;
}

static MOD_UNUSED int bonuses_world_to_col(float x) {
    return bonuses_floor_cell((x - (-2.0f)) / 0.1f);
}

static MOD_UNUSED int bonuses_world_to_row(float y) {
    return bonuses_floor_cell((1.45f - y) / 0.1f);
}

static MOD_UNUSED int bonuses_type_count(void) {
    return (API->bonuses != 0 && API->bonuses->GetTypeCount != 0) ? API->bonuses->GetTypeCount(SELF) : 0;
}

static MOD_UNUSED void bonuses_store_sel_type(const AmodBonusType* t) {
    if (t == 0) return;
    g_bonuses_sel_type = *t;
    bonuses_copy_str(g_bonuses_sel_type_name, BonusesTextCap, t->name);
    bonuses_copy_str(g_bonuses_sel_type_res, BonusesTextCap, t->resourceId);
    g_bonuses_sel_type.name = g_bonuses_sel_type_name;
    g_bonuses_sel_type.resourceId = g_bonuses_sel_type_res;
}

static MOD_UNUSED int bonuses_select_type(const char* name) {
    AmodBonusType t;
    if (API->bonuses == 0 || API->bonuses->FindType == 0 || name == 0) return 0;
    memset(&t, 0, sizeof t);
    t.structSize = sizeof t;
    if (API->bonuses->FindType(SELF, name, &t) == 0) return 0;
    bonuses_store_sel_type(&t);
    return 1;
}

static MOD_UNUSED int bonuses_select_type_at(int index) {
    AmodBonusType t;
    if (API->bonuses == 0 || API->bonuses->GetType == 0) return 0;
    memset(&t, 0, sizeof t);
    t.structSize = sizeof t;
    if (API->bonuses->GetType(SELF, index, &t) == 0) return 0;
    bonuses_store_sel_type(&t);
    return 1;
}

static MOD_UNUSED int bonuses_type_exists(const char* name) {
    AmodBonusType t;
    if (API->bonuses == 0 || API->bonuses->FindType == 0 || name == 0) return 0;
    memset(&t, 0, sizeof t);
    t.structSize = sizeof t;
    return API->bonuses->FindType(SELF, name, &t) != 0 ? 1 : 0;
}

static MOD_UNUSED float bonuses_type_field(const char* name, int which) {
    AmodBonusType t;
    if (API->bonuses == 0 || API->bonuses->FindType == 0 || name == 0) return 0.0f;
    memset(&t, 0, sizeof t);
    t.structSize = sizeof t;
    if (API->bonuses->FindType(SELF, name, &t) == 0) return 0.0f;
    switch (which) {
        case 0: return (float)t.pointsOnTake;
        case 1: return (float)t.pointsOnRunOut;
        case 2: return t.time;
        case 3: return t.burnTime;
        case 4: return t.lightRadius;
        case 5: return t.bonusLightRadius;
        case 6: return (float)t.trainIndex;
        default: return 0.0f;
    }
}

static MOD_UNUSED int bonuses_type_flag(const char* name, int which) {
    AmodBonusType t;
    AmodValue val;
    if (API->bonuses == 0 || name == 0) return 0;
    if (which == 3) {
        if (API->bonuses->GetTypeProperty == 0) return 0;
        memset(&val, 0, sizeof val);
        if (API->bonuses->GetTypeProperty(SELF, name, "timer_is_mine", &val) == 0) return 0;
        return val.integer != 0 ? 1 : 0;
    }
    if (API->bonuses->FindType == 0) return 0;
    memset(&t, 0, sizeof t);
    t.structSize = sizeof t;
    if (API->bonuses->FindType(SELF, name, &t) == 0) return 0;
    if (which == 0) return t.isTotem != 0 ? 1 : 0;
    if (which == 1) return t.isTorch != 0 ? 1 : 0;
    if (which == 2) return t.makesTrain != 0 ? 1 : 0;
    return 0;
}

static MOD_UNUSED const char* bonuses_sel_type_text(int which) {
    return which == 0 ? g_bonuses_sel_type_name : g_bonuses_sel_type_res;
}

static MOD_UNUSED int bonuses_sel_type_int(int which) {
    switch (which) {
        case 0: return g_bonuses_sel_type.pointsOnTake;
        case 1: return g_bonuses_sel_type.pointsOnRunOut;
        case 2: return g_bonuses_sel_type.isTotem;
        case 3: return g_bonuses_sel_type.isTorch;
        case 4: return g_bonuses_sel_type.makesTrain;
        case 5: return g_bonuses_sel_type.trainIndex;
        case 6: return (int)g_bonuses_sel_type.modelId;
        case 7: return (int)g_bonuses_sel_type.textureId;
        case 8: return (int)g_bonuses_sel_type.iconId;
        default: return 0;
    }
}

static MOD_UNUSED float bonuses_sel_type_num(int which) {
    if (which == 0) return g_bonuses_sel_type.time;
    if (which == 1) return g_bonuses_sel_type.burnTime;
    if (which == 2) return g_bonuses_sel_type.lightRadius;
    if (which == 3) return g_bonuses_sel_type.bonusLightRadius;
    if (which >= 4 && which < 8) return g_bonuses_sel_type.glowColor[which - 4];
    return 0.0f;
}

static MOD_UNUSED void bonuses_begin_type(const char* id, const char* basedOn, const char* behavesAs, int ptsTake, int ptsOut) {
    memset(&g_bonuses_def, 0, sizeof g_bonuses_def);
    g_bonuses_def.structSize = sizeof g_bonuses_def;
    bonuses_copy_str(g_bonuses_def_id, BonusesTextCap, id);
    bonuses_copy_str(g_bonuses_def_base, BonusesTextCap, basedOn);
    bonuses_copy_str(g_bonuses_def_behaves, BonusesTextCap, behavesAs);
    g_bonuses_def_model[0] = 0;
    g_bonuses_def_tex[0] = 0;
    g_bonuses_def_icon[0] = 0;
    g_bonuses_def_snd_take[0] = 0;
    g_bonuses_def_snd_use[0] = 0;
    g_bonuses_def.resourceId = g_bonuses_def_id;
    g_bonuses_def.basedOn = g_bonuses_def_base[0] != 0 ? g_bonuses_def_base : 0;
    g_bonuses_def.behavesAs = g_bonuses_def_behaves[0] != 0 ? g_bonuses_def_behaves : 0;
    g_bonuses_def.pointsOnTake = ptsTake;
    g_bonuses_def.pointsOnRunOut = ptsOut;
    g_bonuses_def.fields = AMOD_BONUS_FIELD_POINTS_TAKE | (ptsOut != 0 ? AMOD_BONUS_FIELD_POINTS_OUT : 0u);
}

static MOD_UNUSED void bonuses_type_assets(const char* model, const char* tex, const char* icon, const char* sndTake, const char* sndUse) {
    bonuses_copy_str(g_bonuses_def_model, BonusesTextCap, model);
    bonuses_copy_str(g_bonuses_def_tex, BonusesTextCap, tex);
    bonuses_copy_str(g_bonuses_def_icon, BonusesTextCap, icon);
    bonuses_copy_str(g_bonuses_def_snd_take, BonusesTextCap, sndTake);
    bonuses_copy_str(g_bonuses_def_snd_use, BonusesTextCap, sndUse);
    g_bonuses_def.model = g_bonuses_def_model[0] != 0 ? g_bonuses_def_model : 0;
    g_bonuses_def.texture = g_bonuses_def_tex[0] != 0 ? g_bonuses_def_tex : 0;
    g_bonuses_def.icon = g_bonuses_def_icon[0] != 0 ? g_bonuses_def_icon : 0;
    g_bonuses_def.soundOnTake = g_bonuses_def_snd_take[0] != 0 ? g_bonuses_def_snd_take : 0;
    g_bonuses_def.soundOnUse = g_bonuses_def_snd_use[0] != 0 ? g_bonuses_def_snd_use : 0;
}

static MOD_UNUSED void bonuses_type_timer_train(float seconds, int timerMode, int makesTrain, int trainIdx) {
    g_bonuses_def.time = seconds;
    g_bonuses_def.timer = (AmodBonusTimer)timerMode;
    g_bonuses_def.makesTrain = makesTrain != 0 ? 1 : 0;
    g_bonuses_def.trainIndex = trainIdx;
    g_bonuses_def.fields |= AMOD_BONUS_FIELD_TIME | AMOD_BONUS_FIELD_TIMER | AMOD_BONUS_FIELD_TRAIN;
}

static MOD_UNUSED void bonuses_type_glow(float r, float g, float b, float a, float r2, float g2, float b2, float a2) {
    g_bonuses_def.glowColor[0] = r; g_bonuses_def.glowColor[1] = g; g_bonuses_def.glowColor[2] = b; g_bonuses_def.glowColor[3] = a;
    g_bonuses_def.glowColor2[0] = r2; g_bonuses_def.glowColor2[1] = g2; g_bonuses_def.glowColor2[2] = b2; g_bonuses_def.glowColor2[3] = a2;
    g_bonuses_def.fields |= AMOD_BONUS_FIELD_GLOW | AMOD_BONUS_FIELD_GLOW2;
}

static MOD_UNUSED void bonuses_type_rock_light(float amp, float speed, float ax, float ay, float az, float lr, float lg, float lb, float radius) {
    g_bonuses_def.rockingAmp = amp;
    g_bonuses_def.rockingSpeed = speed;
    g_bonuses_def.rockingAxis[0] = ax; g_bonuses_def.rockingAxis[1] = ay; g_bonuses_def.rockingAxis[2] = az;
    g_bonuses_def.lightColor[0] = lr; g_bonuses_def.lightColor[1] = lg; g_bonuses_def.lightColor[2] = lb;
    g_bonuses_def.lightRadius = radius;
    g_bonuses_def.fields |= AMOD_BONUS_FIELD_ROCKING | AMOD_BONUS_FIELD_LIGHT;
}

static MOD_UNUSED void bonuses_commit_type(void) {
    if (API->bonuses != 0 && API->bonuses->DefineType != 0 && g_bonuses_def_id[0] != 0) {
        g_bonuses_def.structSize = sizeof g_bonuses_def;
        API->bonuses->DefineType(SELF, &g_bonuses_def);
    }
}

static MOD_UNUSED void bonuses_set_type_tex(const char* id, const char* file) {
    if (API->bonuses != 0 && API->bonuses->SetTexture != 0 && id != 0 && file != 0) API->bonuses->SetTexture(SELF, id, file);
}

static MOD_UNUSED void bonuses_set_type_icon(const char* id, const char* file) {
    if (API->bonuses != 0 && API->bonuses->SetIcon != 0 && id != 0 && file != 0) API->bonuses->SetIcon(SELF, id, file);
}

static MOD_UNUSED int bonuses_has_type_prop(const char* id, const char* key) {
    if (API->bonuses == 0 || API->bonuses->HasTypeProperty == 0 || id == 0 || key == 0) return 0;
    return API->bonuses->HasTypeProperty(SELF, id, key);
}

static MOD_UNUSED int bonuses_type_prop_count(void) {
    return (API->bonuses != 0 && API->bonuses->TypePropertyCount != 0) ? API->bonuses->TypePropertyCount(SELF) : 0;
}

static MOD_UNUSED const char* bonuses_type_prop_name(int index) {
    const char* s = (API->bonuses != 0 && API->bonuses->TypePropertyNameAt != 0) ? API->bonuses->TypePropertyNameAt(SELF, index) : "";
    return s != 0 ? s : "";
}

static MOD_UNUSED int bonuses_type_prop_int(const char* id, const char* key) {
    AmodValue v;
    if (API->bonuses == 0 || API->bonuses->GetTypeProperty == 0 || id == 0 || key == 0) return 0;
    memset(&v, 0, sizeof v);
    if (API->bonuses->GetTypeProperty(SELF, id, key, &v) == 0) return 0;
    if (v.kind == AMOD_VALUE_FLOAT) return (int)v.numbers[0];
    return v.integer;
}

static MOD_UNUSED float bonuses_type_prop_num(const char* id, const char* key, int comp) {
    AmodValue v;
    if (API->bonuses == 0 || API->bonuses->GetTypeProperty == 0 || id == 0 || key == 0) return 0.0f;
    memset(&v, 0, sizeof v);
    if (API->bonuses->GetTypeProperty(SELF, id, key, &v) == 0) return 0.0f;
    if (v.kind == AMOD_VALUE_FLOAT) {
        return (comp >= 0 && (uint32_t)comp < v.count) ? v.numbers[comp] : 0.0f;
    }
    return (float)v.integer;
}

static MOD_UNUSED const char* bonuses_type_prop_text(const char* id, const char* key) {
    static char buf[BonusesTextCap];
    AmodValue v;
    buf[0] = 0;
    if (API->bonuses == 0 || API->bonuses->GetTypeProperty == 0 || id == 0 || key == 0) return buf;
    memset(&v, 0, sizeof v);
    if (API->bonuses->GetTypeProperty(SELF, id, key, &v) != 0 && v.kind == AMOD_VALUE_STRING && v.text != 0) {
        bonuses_copy_str(buf, BonusesTextCap, v.text);
    }
    return buf;
}

static MOD_UNUSED void bonuses_set_type_prop_num(const char* id, const char* key, float val) {
    AmodValue cur, out;
    if (API->bonuses == 0 || API->bonuses->SetTypeProperty == 0 || id == 0 || key == 0) return;
    memset(&cur, 0, sizeof cur);
    memset(&out, 0, sizeof out);
    if (API->bonuses->GetTypeProperty != 0 && API->bonuses->GetTypeProperty(SELF, id, key, &cur) != 0 && cur.kind == AMOD_VALUE_FLOAT) {
        out.kind = AMOD_VALUE_FLOAT;
        out.count = 1;
        out.numbers[0] = val;
    } else {
        out.kind = AMOD_VALUE_INT;
        out.integer = (int)val;
    }
    API->bonuses->SetTypeProperty(SELF, id, key, &out);
}

static MOD_UNUSED void bonuses_set_type_prop_vec(const char* id, const char* key, float x, float y, float z, float w) {
    AmodValue out;
    if (API->bonuses == 0 || API->bonuses->SetTypeProperty == 0 || id == 0 || key == 0) return;
    memset(&out, 0, sizeof out);
    out.kind = AMOD_VALUE_FLOAT;
    out.count = (bonuses_str_eq(key, "light_color") || bonuses_str_eq(key, "rocking_axis")) ? 3u : 4u;
    out.numbers[0] = x; out.numbers[1] = y; out.numbers[2] = z; out.numbers[3] = w;
    API->bonuses->SetTypeProperty(SELF, id, key, &out);
}

static MOD_UNUSED void bonuses_set_type_prop_str(const char* id, const char* key, const char* text) {
    AmodValue out;
    if (API->bonuses == 0 || API->bonuses->SetTypeProperty == 0 || id == 0 || key == 0 || text == 0) return;
    memset(&out, 0, sizeof out);
    out.kind = AMOD_VALUE_STRING;
    out.text = text;
    API->bonuses->SetTypeProperty(SELF, id, key, &out);
}

static MOD_UNUSED void bonuses_place_any(int room, const char* name, int col, int row, const char* tag, float seconds, int decor, const char* model, const char* tex) {
    AmodBonusPlacement pl;
    int hasExtra;
    if (API->bonuses == 0 || name == 0 || name[0] == 0) return;
    hasExtra = (tag != 0 && tag[0] != 0) || seconds != 0.0f || decor != 0 || (model != 0 && model[0] != 0) || (tex != 0 && tex[0] != 0);
    if (room < 0 && !hasExtra) {
        if (API->bonuses->Place != 0) API->bonuses->Place(SELF, name, col, row);
        return;
    }
    memset(&pl, 0, sizeof pl);
    pl.structSize = sizeof pl;
    pl.name = name;
    pl.column = col;
    pl.row = row;
    pl.time = seconds;
    pl.tag = (tag != 0 && tag[0] != 0) ? tag : 0;
    pl.decor = decor != 0 ? 1 : 0;
    pl.model = (model != 0 && model[0] != 0) ? model : 0;
    pl.texture = (tex != 0 && tex[0] != 0) ? tex : 0;
    if (room < 0) {
        if (API->bonuses->PlaceEx != 0) API->bonuses->PlaceEx(SELF, &pl);
    } else {
        if (API->bonuses->PlaceIn != 0) API->bonuses->PlaceIn(SELF, room, &pl);
    }
}

static MOD_UNUSED int bonuses_placement_slots(int room) {
    return (API->bonuses != 0 && API->bonuses->PlacementCount != 0) ? API->bonuses->PlacementCount(SELF, room) : 0;
}

static MOD_UNUSED int bonuses_read_placement(int room, int index, AmodBonusSpawnInfo* out) {
    if (API->bonuses == 0 || out == 0) return 0;
    memset(out, 0, sizeof *out);
    out->structSize = sizeof *out;
    if (room < 0 && API->bonuses->GetPlacement != 0) return API->bonuses->GetPlacement(SELF, index, out);
    if (API->bonuses->GetPlacementIn != 0) return API->bonuses->GetPlacementIn(SELF, room, index, out);
    return 0;
}

static MOD_UNUSED int bonuses_select_placement(int room, int index) {
    AmodBonusSpawnInfo info;
    if (bonuses_read_placement(room, index, &info) == 0) return 0;
    g_bonuses_sel_pl = info;
    g_bonuses_sel_pl_idx = index;
    g_bonuses_sel_pl_col = bonuses_world_to_col(info.position[0]);
    g_bonuses_sel_pl_row = bonuses_world_to_row(info.position[1]);
    bonuses_copy_str(g_bonuses_sel_pl_name, BonusesTextCap, info.name);
    bonuses_copy_str(g_bonuses_sel_pl_res, BonusesTextCap, info.resourceId);
    bonuses_copy_str(g_bonuses_sel_pl_tag, BonusesTextCap, info.tag);
    g_bonuses_sel_pl.name = g_bonuses_sel_pl_name;
    g_bonuses_sel_pl.resourceId = g_bonuses_sel_pl_res;
    g_bonuses_sel_pl.tag = g_bonuses_sel_pl_tag;
    return 1;
}

static MOD_UNUSED int bonuses_step_placement(int room, int onlyLive, int index) {
    if (bonuses_select_placement(room, index) == 0) return 0;
    if (onlyLive != 0 && g_bonuses_sel_pl.isLive == 0) return 0;
    return 1;
}

static MOD_UNUSED const char* bonuses_sel_pl_text(int which) {
    if (which == 0) return g_bonuses_sel_pl_name;
    if (which == 1) return g_bonuses_sel_pl_res;
    return g_bonuses_sel_pl_tag;
}

static MOD_UNUSED float bonuses_sel_pl_num(int axis) {
    return (axis >= 0 && axis < 3) ? g_bonuses_sel_pl.position[axis] : 0.0f;
}

static MOD_UNUSED int bonuses_sel_pl_int(int which) {
    switch (which) {
        case 0: return g_bonuses_sel_pl_idx;
        case 1: return g_bonuses_sel_pl_col;
        case 2: return g_bonuses_sel_pl_row;
        case 3: return g_bonuses_sel_pl.isLive;
        case 4: return g_bonuses_sel_pl.hasType;
        case 5: return g_bonuses_sel_pl.kind;
        default: return 0;
    }
}

static MOD_UNUSED int bonuses_room_count(int room, int mode) {
    int total = bonuses_placement_slots(room);
    int i, cnt = 0;
    AmodBonusSpawnInfo info;
    if (mode == 2) return total;
    for (i = 0; i < total; ++i) {
        if (bonuses_read_placement(room, i, &info) == 0) continue;
        if (mode == 0 && info.isLive == 0) continue;
        ++cnt;
    }
    return cnt;
}

static MOD_UNUSED int bonuses_named_count(const char* name) {
    int total = bonuses_placement_slots(-1);
    int i, cnt = 0;
    AmodBonusSpawnInfo info;
    if (name == 0 || name[0] == 0) return 0;
    for (i = 0; i < total; ++i) {
        if (bonuses_read_placement(-1, i, &info) == 0 || info.isLive == 0) continue;
        if (bonuses_str_eq(info.name, name) || bonuses_str_eq(info.resourceId, name)) ++cnt;
    }
    return cnt;
}

static MOD_UNUSED int bonuses_index_of_tag(const char* tag, int nth) {
    int total = bonuses_placement_slots(-1);
    int i, seen = 0;
    AmodBonusSpawnInfo info;
    if (tag == 0 || tag[0] == 0) return -1;
    for (i = 0; i < total; ++i) {
        if (bonuses_read_placement(-1, i, &info) == 0 || info.isLive == 0) continue;
        if (info.tag != 0 && bonuses_str_eq(info.tag, tag)) {
            if (seen == nth) return i;
            ++seen;
        }
    }
    return -1;
}

static MOD_UNUSED int bonuses_index_at_cell(int col, int row) {
    int total = bonuses_placement_slots(-1);
    int i;
    AmodBonusSpawnInfo info;
    for (i = 0; i < total; ++i) {
        if (bonuses_read_placement(-1, i, &info) == 0 || info.isLive == 0) continue;
        if (bonuses_world_to_col(info.position[0]) == col && bonuses_world_to_row(info.position[1]) == row) return i;
    }
    return -1;
}

static MOD_UNUSED int bonuses_placement_is_live(int room, int index) {
    AmodBonusSpawnInfo info;
    if (bonuses_read_placement(room, index, &info) == 0) return 0;
    return info.isLive != 0 ? 1 : 0;
}

static MOD_UNUSED int bonuses_placement_matches(int room, int index, const char* text) {
    AmodBonusSpawnInfo info;
    if (text == 0 || text[0] == 0 || bonuses_read_placement(room, index, &info) == 0) return 0;
    return (bonuses_str_eq(info.name, text) || bonuses_str_eq(info.resourceId, text) || bonuses_str_eq(info.tag, text)) ? 1 : 0;
}

static MOD_UNUSED void bonuses_remove_placement(int room, int index) {
    if (API->bonuses == 0) return;
    if (room < 0 && API->bonuses->RemovePlacement != 0) API->bonuses->RemovePlacement(SELF, index);
    else if (API->bonuses->RemovePlacementIn != 0) API->bonuses->RemovePlacementIn(SELF, room, index);
