static MOD_UNUSED int __cdecl bonuses_kind_mux(const AmodBonusKindInfo* kinfo, void* user) {
    int slotIdx = (int)(intptr_t)user;
    int i, ans;
    BonusesKindSlot* slot;
    if (kinfo == 0 || slotIdx < 0 || slotIdx >= g_bonuses_kind_cnt) return 0;
    slot = &g_bonuses_kinds[slotIdx];
    g_bonuses_body_ptr = kinfo->body;
    if (kinfo->body != 0) bonuses_cache_body(kinfo->body);

    if (kinfo->event == AMOD_BONUS_EVENT_BUILD) {
        if (kinfo->body != 0) {
            if (kinfo->body->model == 0 && kinfo->body->modelId == 0) kinfo->body->model = "models/bonus/d_3.mmd";
            if (kinfo->body->texture == 0 && kinfo->body->textureId == 0) kinfo->body->texture = "textures/bonus/d_3.jpg";
            kinfo->body->glowColor[0] = 1.0f; kinfo->body->glowColor[1] = 0.9f; kinfo->body->glowColor[2] = 0.4f; kinfo->body->glowColor[3] = 1.0f;
            kinfo->body->glowColor2[0] = 0.3f; kinfo->body->glowColor2[1] = 0.8f; kinfo->body->glowColor2[2] = 1.0f; kinfo->body->glowColor2[3] = 1.0f;
            kinfo->body->rockingAmp = 0.5f;
            kinfo->body->rockingSpeed = 4.0f;
            kinfo->body->rockingAxis[0] = 1.0f; kinfo->body->rockingAxis[1] = 1.0f; kinfo->body->rockingAxis[2] = 0.0f;
            kinfo->body->pointsOnTake = 100;
            bonuses_cache_body(kinfo->body);
        }
        ans = 1;
        for (i = 0; i < slot->buildCnt; ++i) {
            if (slot->buildFns[i] != 0 && slot->buildFns[i](kinfo, 0) == 0) ans = 0;
        }
        if (kinfo->body != 0) bonuses_cache_body(kinfo->body);
        g_bonuses_body_ptr = 0;
        return ans;
    }

    if (kinfo->event == AMOD_BONUS_EVENT_UPDATE) {
        g_bonuses_kind_dt = kinfo->deltaTime;
        ans = 0;
        for (i = 0; i < slot->updateCnt; ++i) {
            if (slot->updateFns[i] != 0 && slot->updateFns[i](kinfo, 0) != 0) ans = 1;
        }
        if (kinfo->body != 0) bonuses_cache_body(kinfo->body);
        g_bonuses_body_ptr = 0;
        return ans;
    }

    if (kinfo->event == AMOD_BONUS_EVENT_TAKE) {
        bonuses_cache_take(kinfo->take);
        g_bonuses_take_verdict = AMOD_BONUS_TAKE_DEFAULT;
        for (i = 0; i < slot->takeCnt; ++i) {
            if (slot->takeFns[i] != 0) {
                int r = slot->takeFns[i](kinfo, 0);
                if (r != AMOD_BONUS_TAKE_DEFAULT) g_bonuses_take_verdict = r;
            }
        }
        g_bonuses_body_ptr = 0;
        return g_bonuses_take_verdict;
    }

    g_bonuses_body_ptr = 0;
    return 0;
}

static MOD_UNUSED int bonuses_find_or_make_slot(const char* name) {
    int i;
    if (name == 0 || name[0] == 0) return -1;
    for (i = 0; i < g_bonuses_kind_cnt; ++i) {
        if (bonuses_str_eq(g_bonuses_kinds[i].name, name)) return i;
    }
    if (g_bonuses_kind_cnt >= BonusesMaxKinds) return -1;
    i = g_bonuses_kind_cnt++;
    memset(&g_bonuses_kinds[i], 0, sizeof g_bonuses_kinds[i]);
    bonuses_copy_str(g_bonuses_kinds[i].name, 64, name);
    return i;
}

static MOD_UNUSED int bonuses_ensure_kind(const char* name) {
    int idx = bonuses_find_or_make_slot(name);
    if (idx < 0) return 0;
    if (g_bonuses_kinds[idx].kindId == 0 && API->bonuses != 0 && API->bonuses->RegisterKind != 0) {
        g_bonuses_kinds[idx].kindId = API->bonuses->RegisterKind(SELF, g_bonuses_kinds[idx].name, bonuses_kind_mux, (void*)(intptr_t)idx);
    }
    return g_bonuses_kinds[idx].kindId;
}

static MOD_UNUSED int bonuses_find_kind_id(const char* name) {
    int i;
    if (name == 0 || name[0] == 0) return 0;
    for (i = 0; i < g_bonuses_kind_cnt; ++i) {
        if (bonuses_str_eq(g_bonuses_kinds[i].name, name)) return g_bonuses_kinds[i].kindId;
    }
    return 0;
}

static MOD_UNUSED void bonuses_bind_kind(const char* name, int whichEvent, AmodBonusKindHandler fn) {
    int idx = bonuses_find_or_make_slot(name);
    if (idx < 0 || fn == 0) return;
    bonuses_ensure_kind(name);
    if (whichEvent == 0 && g_bonuses_kinds[idx].buildCnt < BonusesMaxKindHooks) {
        g_bonuses_kinds[idx].buildFns[g_bonuses_kinds[idx].buildCnt++] = fn;
    } else if (whichEvent == 1 && g_bonuses_kinds[idx].updateCnt < BonusesMaxKindHooks) {
        g_bonuses_kinds[idx].updateFns[g_bonuses_kinds[idx].updateCnt++] = fn;
    } else if (whichEvent == 2 && g_bonuses_kinds[idx].takeCnt < BonusesMaxKindHooks) {
        g_bonuses_kinds[idx].takeFns[g_bonuses_kinds[idx].takeCnt++] = fn;
    }
}

static MOD_UNUSED void bonuses_place_kind(int room, const char* kindName, int col, int row, const char* tag, int decor) {
    int kindId = bonuses_ensure_kind(kindName);
    AmodBonusPlacement pl;
    if (kindId == 0 || API->bonuses == 0) return;
    memset(&pl, 0, sizeof pl);
    pl.structSize = sizeof pl;
    pl.name = kindName;
    pl.column = col;
    pl.row = row;
    pl.tag = (tag != 0 && tag[0] != 0) ? tag : 0;
    pl.decor = decor != 0 ? 1 : 0;
    if (room < 0) {
        if (API->bonuses->PlaceKind != 0) API->bonuses->PlaceKind(SELF, kindId, &pl);
    } else {
        if (API->bonuses->PlaceKindIn != 0) API->bonuses->PlaceKindIn(SELF, kindId, room, &pl);
    }
}

